// ============================================================================
// TS_Demux_apb: APB4 register wrapper around TS_Demux_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/TS_Demux.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/TS_Demux.md
// ============================================================================
module TS_Demux_apb #(
  parameter logic [3:0] AXI_ID = 4'd3
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic ts_valid,
  input logic ts_sync,
  input logic [7:0] ts_data,
  input logic ts_err,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h7C020100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [14:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd15) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_enable;
  logic [3:0]    c_pid_en;
  logic [12:0]   c_pid0;
  logic [12:0]   c_pid1;
  logic [12:0]   c_pid2;
  logic [12:0]   c_pid3;
  logic [31:0]   c_ring_base;
  logic [15:0]   c_ring_pkts;
  logic [15:0]   c_rd_idx;
  logic [15:0]   c_wr_idx;
  logic [15:0]   c_pkt_cnt;
  logic [15:0]   c_drop_cnt;
  logic [15:0]   c_cc_err_cnt;
  logic [15:0]   c_ovf_cnt;
  logic          c_busy;
  logic          c_err;
  logic          c_pkt;
  logic          c_drop;
  logic          c_cc_err;
  logic          c_err_irq;
  TS_Demux_top #(.AXI_ID(AXI_ID)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .ts_valid(ts_valid),
    .ts_sync(ts_sync),
    .ts_data(ts_data),
    .ts_err(ts_err),
    .enable(c_enable),
    .pid_en(c_pid_en),
    .pid0(c_pid0),
    .pid1(c_pid1),
    .pid2(c_pid2),
    .pid3(c_pid3),
    .ring_base(c_ring_base),
    .ring_pkts(c_ring_pkts),
    .rd_idx(c_rd_idx),
    .wr_idx(c_wr_idx),
    .pkt_cnt(c_pkt_cnt),
    .drop_cnt(c_drop_cnt),
    .cc_err_cnt(c_cc_err_cnt),
    .ovf_cnt(c_ovf_cnt),
    .busy(c_busy),
    .err(c_err),
    .pkt(c_pkt),
    .drop(c_drop),
    .cc_err(c_cc_err),
    .err_irq(c_err_irq),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );

  // ---------------- registers ----------------
  logic [3:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [4:0] r_CTRL;   // 12'h014 CTRL
  logic [25:0] r_PID01;   // 12'h018 PID01
  logic [25:0] r_PID23;   // 12'h01C PID23
  logic [31:0] r_RING_BASE;   // 12'h020 RING_BASE
  logic [15:0] r_RING_PKTS;   // 12'h024 RING_PKTS
  logic [15:0] r_RD_IDX;   // 12'h028 RD_IDX

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 5'h0;
      r_PID01 <= 26'h0;
      r_PID23 <= 26'h0;
      r_RING_BASE <= 32'h0;
      r_RING_PKTS <= 16'h0;
      r_RD_IDX <= 16'h0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[3:0] & wmask[3:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[6]) r_PID01 <= (r_PID01 & ~wmask[25:0]) | (PWDATA[25:0] & wmask[25:0]);
      if (wr && hit[7]) r_PID23 <= (r_PID23 & ~wmask[25:0]) | (PWDATA[25:0] & wmask[25:0]);
      if (wr && hit[8]) r_RING_BASE <= (r_RING_BASE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_RING_PKTS <= (r_RING_PKTS & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[10]) r_RD_IDX <= (r_RD_IDX & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
    end
  end

  // ---------------- core inputs ----------------
  assign c_enable = r_CTRL[0:0];
  assign c_pid_en = r_CTRL[4:1];
  assign c_pid0 = r_PID01[12:0];
  assign c_pid1 = r_PID01[25:13];
  assign c_pid2 = r_PID23[12:0];
  assign c_pid3 = r_PID23[25:13];
  assign c_ring_base = r_RING_BASE[31:0];
  assign c_ring_pkts = r_RING_PKTS[15:0];
  assign c_rd_idx = r_RD_IDX[15:0];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_pkt;
    irq_set[1] = c_drop;
    irq_set[2] = c_cc_err;
    irq_set[3] = c_err_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_PID01);
      10'd7: apb_rdata = 32'(r_PID23);
      10'd8: apb_rdata = 32'(r_RING_BASE);
      10'd9: apb_rdata = 32'(r_RING_PKTS);
      10'd10: apb_rdata = 32'(r_RD_IDX);
      10'd11: apb_rdata = 32'({c_wr_idx});
      10'd12: apb_rdata = 32'({c_err, c_busy});
      10'd13: apb_rdata = 32'({c_drop_cnt, c_pkt_cnt});
      10'd14: apb_rdata = 32'({c_ovf_cnt, c_cc_err_cnt});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
